package io.github.diodeme.ji.host;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;

/** Immutable durable follow-up/steer queue with whole-queue revision CAS. */
public record FollowUpQueue(long revision, boolean paused, List<Item> items) {
    public FollowUpQueue {
        if (revision < 0) throw new IllegalArgumentException("queue revision must be non-negative");
        items = List.copyOf(items);
        var ids = new HashSet<String>();
        var commandIds = new HashSet<String>();
        for (int index = 0; index < items.size(); index++) {
            Item item = items.get(index);
            if (item.order() != index || !ids.add(item.itemId()) || !commandIds.add(item.commandId())) {
                throw new IllegalArgumentException("queue identity and order must be unique and contiguous");
            }
        }
    }

    public static FollowUpQueue empty() {
        return new FollowUpQueue(0, false, List.of());
    }

    public FollowUpQueue enqueue(Item item, long expectedRevision) {
        requireRevision(expectedRevision);
        if (items.stream().anyMatch(candidate -> candidate.itemId().equals(item.itemId())
                || candidate.commandId().equals(item.commandId()))) {
            throw new IllegalStateException("queue item already exists");
        }
        var next = new ArrayList<>(items);
        next.add(item.withOrder(next.size()));
        return next(paused, next);
    }

    public FollowUpQueue reorder(List<String> itemIds, long expectedRevision) {
        requireRevision(expectedRevision);
        if (itemIds.size() != items.size() || new HashSet<>(itemIds).size() != itemIds.size()) {
            throw new IllegalArgumentException("reorder must contain every item exactly once");
        }
        Map<String, Item> byId = items.stream().collect(java.util.stream.Collectors.toMap(Item::itemId, value -> value));
        var next = new ArrayList<Item>();
        for (int index = 0; index < itemIds.size(); index++) {
            Item item = byId.get(itemIds.get(index));
            if (item == null) throw new IllegalArgumentException("reorder contains unknown item");
            next.add(item.withOrder(index));
        }
        if (next.equals(items)) throw new IllegalArgumentException("queue transition must change items");
        return next(paused, next);
    }

    public FollowUpQueue promote(String itemId, long expectedRevision) {
        requireRevision(expectedRevision);
        var next = new ArrayList<Item>();
        boolean found = false;
        for (Item item : items) {
            if (item.itemId().equals(itemId)) {
                if (item.kind() == Kind.STEER) throw new IllegalStateException("steer cannot be demoted or promoted twice");
                next.add(item.withKind(Kind.STEER));
                found = true;
            } else next.add(item);
        }
        if (!found) throw new IllegalArgumentException("queue item not found");
        return next(paused, reindex(next));
    }

    public Removed remove(String itemId, String requestingClientId, long expectedRevision) {
        requireRevision(expectedRevision);
        Item removed = items.stream().filter(item -> item.itemId().equals(itemId)).findFirst()
                .orElseThrow(() -> new IllegalArgumentException("queue item not found"));
        var remaining = items.stream().filter(item -> !item.itemId().equals(itemId)).toList();
        FollowUpQueue queue = next(paused, reindex(remaining));
        return new Removed(queue, new ComposerDraft(requestingClientId, removed.content(), removed.attachments()));
    }

    public Consumed consumeSteer(long expectedRevision) {
        requireRevision(expectedRevision);
        if (paused) return new Consumed(this, Optional.empty());
        Item steer = items.stream().filter(item -> item.kind() == Kind.STEER).findFirst().orElse(null);
        if (steer == null) return new Consumed(this, Optional.empty());
        var remaining = items.stream().filter(item -> !item.itemId().equals(steer.itemId())).toList();
        return new Consumed(next(false, reindex(remaining)), Optional.of(steer));
    }

    public FollowUpQueue rollbackUninjectedSteer(Item item, long expectedRevision) {
        requireRevision(expectedRevision);
        if (item.kind() != Kind.STEER) throw new IllegalArgumentException("only steer may roll back");
        var next = new ArrayList<Item>();
        next.add(item.withOrder(0));
        next.addAll(items);
        return next(paused, reindex(next));
    }

    public FollowUpQueue pause(long expectedRevision) {
        requireRevision(expectedRevision);
        if (paused) throw new IllegalStateException("queue already paused");
        return next(true, items);
    }

    public FollowUpQueue resume(long expectedRevision) {
        requireRevision(expectedRevision);
        if (!paused) throw new IllegalStateException("queue is not paused");
        return next(false, items);
    }

    private FollowUpQueue next(boolean nextPaused, List<Item> nextItems) {
        return new FollowUpQueue(Math.incrementExact(revision), nextPaused, nextItems);
    }

    private void requireRevision(long expectedRevision) {
        if (revision != expectedRevision) {
            throw new IllegalStateException("queue revision conflict: expected " + expectedRevision + ", current " + revision);
        }
    }

    private static List<Item> reindex(List<Item> source) {
        var result = new ArrayList<Item>();
        for (int index = 0; index < source.size(); index++) result.add(source.get(index).withOrder(index));
        return List.copyOf(result);
    }

    public enum Kind { FOLLOW_UP, STEER }

    public record Item(String itemId, String commandId, long acceptedSeq, int order, Kind kind,
                       String clientId, List<String> content, List<String> attachments) {
        public Item {
            requireText(itemId, "itemId");
            requireText(commandId, "commandId");
            if (acceptedSeq < 1 || order < 0) throw new IllegalArgumentException("queue counters are invalid");
            Objects.requireNonNull(kind, "kind");
            requireText(clientId, "clientId");
            content = List.copyOf(content);
            attachments = List.copyOf(attachments);
            if (content.isEmpty() && attachments.isEmpty()) throw new IllegalArgumentException("queue item must contain content");
        }
        private Item withOrder(int next) { return new Item(itemId, commandId, acceptedSeq, next, kind, clientId, content, attachments); }
        private Item withKind(Kind next) { return new Item(itemId, commandId, acceptedSeq, order, next, clientId, content, attachments); }
    }

    public record ComposerDraft(String clientId, List<String> content, List<String> attachments) {
        public ComposerDraft {
            requireText(clientId, "clientId");
            content = List.copyOf(content);
            attachments = List.copyOf(attachments);
        }
    }
    public record Removed(FollowUpQueue queue, ComposerDraft draft) {}
    public record Consumed(FollowUpQueue queue, Optional<Item> item) {
        public Consumed { item = item == null ? Optional.empty() : item; }
    }

    private static void requireText(String value, String name) {
        if (value == null || value.isBlank()) throw new IllegalArgumentException(name + " must not be blank");
    }
}

